# Generated by Descant: acceptance tests.

require "timekeeping_relay"

RSpec.describe TimekeepingRelay::IdempotencyKey do
  it "derives one stable UUID per batch body and a different one when the same positions carry other content" do
    batch = lambda do |generation:, version:, entry_id: 10|
      { "schema_version" => 1,
        "snapshots" => [{ "generation" => generation, "outbox_position" => 1,
                          "entry" => { "id" => entry_id, "company_id" => 1, "version" => version } }] }
    end
    reordered = { "snapshots" => [{ "entry" => { "version" => 1, "company_id" => 1, "id" => 10 },
                                    "outbox_position" => 1, "generation" => 2 }],
                  "schema_version" => 1 }

    key = described_class.for(batch.call(generation: 2, version: 1))

    expect(key).to match(/\A\h{8}-\h{4}-5\h{3}-[89ab]\h{3}-\h{12}\z/)
    # A resend of the same rows keeps its key, so the consumer replays its stored answer.
    expect(described_class.for(batch.call(generation: 2, version: 1))).to eq(key)
    expect(described_class.for(reordered)).to eq(key)
    # Two outboxes, or two owner generations, can reuse position 1 for other entries.
    expect(described_class.for(batch.call(generation: 3, version: 1))).not_to eq(key)
    expect(described_class.for(batch.call(generation: 2, version: 2))).not_to eq(key)
    expect(described_class.for(batch.call(generation: 2, version: 1, entry_id: 11))).not_to eq(key)
  end
end
